BEGIN;
-- Preserve former renderer text without rewriting issued source JSON/events
-- or treating historic boilerplate as reviewed vendor-master defaults.
CREATE TABLE purchase_indent_legacy_terms (
 document_id uuid PRIMARY KEY REFERENCES purchase_indent_documents(id),
 terms jsonb NOT NULL CHECK(jsonb_typeof(terms)='object' AND terms->>'source'='legacy_template_v1'),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 created_by_id uuid REFERENCES users(id)
);
INSERT INTO purchase_indent_legacy_terms(document_id,terms)
SELECT id,$legacy${"source": "legacy_template_v1", "notes": ["BPCL / Client / Third Party Inspection (TPI) is applicable on the items.", "All materials shall be strictly as per enclosed tender technical specification, BOQ description and approved documents.", "Vendor shall provide the GA drawing, TDS and other technical documents for approval from end client as per the technical specification of the tender enclosed.", "Guaranty / Warranty: 5 years onsite warranty/guarantee from the date of commissioning or 5 Years + 6 Months from the date of supply whichever is later.", "Vendor has to provide following documents for approval from end client: (i) BIS certificate (ii) NABL certificate (iii) TDS (iv) LM-79 (v) LM-80 (vi) TTC (vii) Photobiological Report (viii) Other relevant test certificates (ix) QAP."], "conditions": ["Price Basis: The rates quoted are F.O.R. destination site.", "Inspection: Client/TPI inspection at manufacturer's premises shall be done before the dispatch of material. It is the responsibility of the manufacturer to satisfy the client/TPI technically during the inspection and in line with approved documents. (Cost of TPI in Vendor's Scope).", "Inspection Call: Inspection call shall be raised at least 15 days prior to the date of inspection.", "Inspection Failure: If the inspection fails and is rejected, Vendor shall be liable to pay the damages caused and shall compensate for the losses so incurred to Vishal Technopower Private Limited.", "Delivery time: Within agreed schedule from the date of P.O.", "Technical Compliance: Vendor to comply with all technical specifications strictly as per approved documents provided by us and provide stamped signed acknowledgement of the same.", "Technical Documents: All technical documents along with QAP to be submitted within 2 days from the date of LOI for approval from the end client.", "Dispatch: Material shall only be dispatched after receiving dispatch clearance from us.", "Deviation: Any deviation either in quantity or technical specification shall have written approval, or else it will not be likely to be paid or accepted.", "Part-Delivery: Until & otherwise specified, material shall be supplied in 1 & only 1 single lot.", "Prices: Prices will be firm and final and shall not be revised at any cost till completion of order.", "Indemnification: The vendor shall indemnify and hold harmless Vishal Technopower Private Limited from any claims, damages, or losses arising due to defects in supplied materials.", "Confidentiality: Both parties agree to maintain the confidentiality of all proprietary and technical information exchanged.", "Termination: Vishal Technopower Private Limited reserves the right to terminate this Purchase Order in the event of failure to meet timeline or quality standards with 7 days notice.", "Dispute Resolution: Any dispute shall be referred to arbitration as per the Arbitration & Conciliation Act, 1996, with the venue of arbitration in Ghaziabad, Uttar Pradesh.", "Compliance with Laws: The vendor must comply with all applicable statutory and regulatory requirements including GST and labor regulations."], "delivery_basis": "F.O.R. destination site."}$legacy$::jsonb
FROM purchase_indent_documents WHERE data->'terms' IS NULL;
CREATE TRIGGER purchase_indent_legacy_terms_immutable BEFORE UPDATE OR DELETE ON purchase_indent_legacy_terms FOR EACH ROW EXECUTE FUNCTION protect_indent_document_evidence();
CREATE TRIGGER purchase_indent_legacy_terms_no_truncate BEFORE TRUNCATE ON purchase_indent_legacy_terms FOR EACH STATEMENT EXECUTE FUNCTION protect_indent_document_evidence();
COMMIT;
